            if((Number(!!(Number(C.i32((newtyp))==C.LAVAPOOL)||Number(C.i32((newtyp))==C.LAVAWALL))))) (W135((A44(A74(C.svl))+Number(x)*(C.sizes["struct rm"]*21))+Number(y)*C.sizes["struct rm"],C.u32(1)));
